let paidR2DailyStart=null;
if(lane==='core'&&process.argv.includes('--publish')){
 try{
  const {paidDates}=await import('./marketparquet-paid-store.mjs');
  paidR2DailyStart={
   stock:paidDates(base,'stock_daily').length,
   etf:paidDates(base,'etf_daily').length,
  };
 }catch{}
}

// R2 Archive uses only the existing Core source pin and remaining 40-file budget.
if(lane==='core'&&process.argv.includes('--publish')){
 try{
  const {checkApprovedPcRuntime}=await import('./us-breadth-paid-r2-cycle.mjs');
  const approved=checkApprovedPcRuntime(base);
  if(!approved.ok){
   console.log('US_BREADTH_PAID_R2_BACKFILL '+JSON.stringify({status:approved.status,downloaded:0}));
  }else if(!paidR2DailyStart){
   console.log('US_BREADTH_PAID_R2_BACKFILL '+JSON.stringify({status:'PAID_R2_CURRENT_COLLECTION_UNVERIFIED',downloaded:0}));
  }else{
   const {paidDates,collectPaidDaily}=await import('./marketparquet-paid-store.mjs');
   const used=(paidDates(base,'stock_daily').length-paidR2DailyStart.stock)
    +(paidDates(base,'etf_daily').length-paidR2DailyStart.etf);
   if(!Number.isSafeInteger(used)||used<0||used>40){
    console.log('US_BREADTH_PAID_R2_BACKFILL '+JSON.stringify({status:'PAID_R2_CURRENT_COLLECTION_UNVERIFIED',downloaded:0}));
   }else{
    const {planStoredPaidUsR2Backfill}=await import('./us-breadth-paid-r2-stored.mjs');
    const plan=await planStoredPaidUsR2Backfill(base);
    if(plan.prepared!==true||plan.missingCount===0||used===40){
     console.log('US_BREADTH_PAID_R2_BACKFILL '+JSON.stringify({
      status:plan.prepared!==true?plan.status:plan.missingCount===0?plan.status:'PAID_R2_BACKFILL_BUDGET_EXHAUSTED',
      missingCount:plan.missingCount??null,downloaded:0,
     }));
    }else{
     const report=await collectPaidDaily(base,{
      start:plan.firstDate,end:plan.lastDate,maxFiles:40-used,
      assetTypes:['stock_daily'],
     });
     console.log('US_BREADTH_PAID_R2_BACKFILL '+JSON.stringify({
      status:report.status,firstDate:plan.firstDate,lastDate:plan.lastDate,
      missingBefore:plan.missingCount,downloaded:report.downloaded,
      remaining:report.remaining,providerCalls:report.apiRequests,
      d1Writes:report.d1Writes,
     }));
    }
   }
  }
 }catch(e){
  console.warn('US_BREADTH_PAID_R2_BACKFILL '+JSON.stringify({
   status:'FAILED_PREVIOUS_INPUTS_PRESERVED',
   code:/^(?:US_PAID_R2_|PAID_R2_|MP_PAID_)[A-Z0-9_]+$/.test(String(e?.code??''))
    ?e.code:'PAID_R2_BACKFILL_FAILED',
  }));
 }
}
